use csv_core::{Reader, ReaderBuilder, ReadRecordResult, ReadFieldResult};

fn run_record(nfa: bool, chunks: &[&[u8]], outcap: usize, endscap: usize) -> Vec<Vec<Vec<u8>>> {
    let mut b = ReaderBuilder::new();
    b.nfa(nfa);
    let mut rdr = b.build();
    let mut recs = vec![];
    let mut output = vec![0u8; outcap];
    let mut outpos = 0usize;
    let mut ends = vec![0usize; endscap];
    let mut endpos = 0usize;
    for chunk in chunks {
        let mut data = *chunk;
        loop {
            let (res, nin, nout, nend) = rdr.read_record(
                data,
                &mut output[outpos..],
                &mut ends[endpos..],
            );
            data = &data[nin..];
            outpos += nout;
            endpos += nend;
            match res {
                ReadRecordResult::InputEmpty => break,
                ReadRecordResult::OutputFull | ReadRecordResult::OutputEndsFull => {
                    if res == ReadRecordResult::OutputFull {
                        let nl = output.len() * 2;
                        output.resize(nl, 0);
                    } else {
                        let nl = ends.len() * 2;
                        ends.resize(nl, 0);
                    }
                }
                ReadRecordResult::Record => {
                    let mut start = 0;
                    let mut row = vec![];
                    for &e in &ends[..endpos] {
                        row.push(output[start..e].to_vec());
                        start = e;
                    }
                    recs.push(row);
                    outpos = 0;
                    endpos = 0;
                }
                ReadRecordResult::End => {
                    return recs;
                }
            }
        }
    }
    // drain
    loop {
        let (res, _, nout, nend) = rdr.read_record(&[], &mut output[outpos..], &mut ends[endpos..]);
        outpos += nout;
        endpos += nend;
        match res {
            ReadRecordResult::Record => {
                let mut start = 0;
                let mut row = vec![];
                for &e in &ends[..endpos] {
                    row.push(output[start..e].to_vec());
                    start = e;
                }
                recs.push(row);
                outpos = 0;
                endpos = 0;
            }
            ReadRecordResult::OutputFull => {
                let nl = output.len() * 2;
                output.resize(nl, 0);
            }
            ReadRecordResult::OutputEndsFull => {
                let nl = ends.len() * 2;
                ends.resize(nl, 0);
            }
            ReadRecordResult::InputEmpty => panic!("InputEmpty on empty input"),
            ReadRecordResult::End => return recs,
        }
    }
}

fn run_field(nfa: bool, chunks: &[&[u8]], cap: usize) -> Vec<Vec<Vec<u8>>> {
    let mut b = ReaderBuilder::new();
    b.nfa(nfa);
    let mut rdr = b.build();
    let mut recs = vec![];
    let mut row = vec![];
    let mut field = vec![0u8; cap];
    let mut pos = 0;
    for chunk in chunks {
        let mut data = *chunk;
        loop {
            let (res, nin, nout) = rdr.read_field(data, &mut field[pos..]);
            data = &data[nin..];
            pos += nout;
            match res {
                ReadFieldResult::InputEmpty => break,
                ReadFieldResult::OutputFull => {
                    let nl = field.len() * 2;
                    field.resize(nl, 0);
                }
                ReadFieldResult::Field { record_end } => {
                    row.push(field[..pos].to_vec());
                    pos = 0;
                    if record_end {
                        recs.push(std::mem::take(&mut row));
                    }
                }
                ReadFieldResult::End => return recs,
            }
        }
    }
    loop {
        let (res, _, nout) = rdr.read_field(&[], &mut field[pos..]);
        pos += nout;
        match res {
            ReadFieldResult::Field { record_end } => {
                row.push(field[..pos].to_vec());
                pos = 0;
                if record_end {
                    recs.push(std::mem::take(&mut row));
                }
            }
            ReadFieldResult::OutputFull => {
                let nl = field.len() * 2;
                field.resize(nl, 0);
            }
            ReadFieldResult::InputEmpty => panic!("InputEmpty empty"),
            ReadFieldResult::End => return recs,
        }
    }
}

#[test]
fn scratch_record_frag() {
    let data: &[u8] = b"a,b\nc";
    for nfa in [false, true] {
        // full
        println!("rec nfa={} full = {:?}", nfa, run_record(nfa, &[data], 1024, 10));
        // output fragments
        println!("rec nfa={} out1 = {:?}", nfa, run_record(nfa, &[data], 1, 10));
        // input fragments 1 byte each
        let ones: Vec<&[u8]> = (0..data.len()).map(|i| &data[i..i+1]).collect();
        println!("rec nfa={} in1out1 = {:?}", nfa, run_record(nfa, &ones, 1, 10));
        println!("fld nfa={} cap1 = {:?}", nfa, run_field(nfa, &ones, 1));
        println!("fld nfa={} full = {:?}", nfa, run_field(nfa, &[data], 1024));
    }
}
