pub fn read_field(
    &mut self,
    input: &[u8],
    output: &mut [u8],
) -> (ReadFieldResult, usize, usize) {
    let rest = self.bom_classify(input);
    // Bytes of this call's input already accepted while detecting the
    // BOM (a stripped signature or a retained candidate prefix).
    let mut nin = input.len() - rest.len();
    let mut nout_total = 0;

    // Flush bytes released by BOM detection in earlier calls first.
    let staged = self.bom_staged();
    let mut output = output;
    if !staged.is_empty() {
        let (res, c, nout) = if self.use_nfa {
            self.read_field_nfa(&staged, output)
        } else {
            self.read_field_dfa(&staged, output)
        };
        self.bom_consume_staged(c);
        nout_total += nout;
        output = &mut { output }[nout..];
        if res != ReadFieldResult::InputEmpty {
            return (res, nin, nout_total);
        }
    }
    if !rest.is_empty() {
        let (res, c, nout) = if self.use_nfa {
            self.read_field_nfa(rest, output)
        } else {
            self.read_field_dfa(rest, output)
        };
        (res, nin + c, nout_total + nout)
    } else if input.is_empty() {
        // Only an explicitly empty input from the caller may signal end.
        let (res, _, nout) = if self.use_nfa {
            self.read_field_nfa(&[], output)
        } else {
            self.read_field_dfa(&[], output)
        };
        (res, 0, nout_total + nout)
    } else {
        // A non-empty call was wholly absorbed by BOM detection (e.g. it
        // contained only the BOM). Do not report the end here.
        let _ = nin;
        nin = input.len() - rest.len();
        (ReadFieldResult::InputEmpty, nin, nout_total)
    }
}

