use csv_core::{ReaderBuilder, ReadRecordResult};

// Exact convention used by the high-level csv reader: slice buffers at the
// already-filled offset, grow on OutputFull/OutputEndsFull.
fn run(nfa: bool, data: &[u8], initcap: usize) -> Vec<Vec<Vec<u8>>> {
    let mut b = ReaderBuilder::new();
    b.nfa(nfa);
    let mut rdr = b.build();
    let mut fields = vec![0u8; initcap];
    let mut ends = vec![0usize; 4];
    let (mut outlen, mut endlen) = (0usize, 0usize);
    let mut recs = vec![];
    let mut input = data;
    loop {
        let (res, nin, nout, nend) = rdr.read_record(
            input,
            &mut fields[outlen..],
            &mut ends[endlen..],
        );
        input = &input[nin..];
        outlen += nout;
        endlen += nend;
        match res {
            ReadRecordResult::InputEmpty => {
                if input.is_empty() {
                    input = &[];
                }
            }
            ReadRecordResult::OutputFull => {
                let nl = fields.len() * 2;
                fields.resize(nl, 0);
            }
            ReadRecordResult::OutputEndsFull => {
                ends.resize(ends.len() * 2, 0);
            }
            ReadRecordResult::Record => {
                let mut start = 0;
                let mut row = vec![];
                for &e in &ends[..endlen] {
                    row.push(fields[start..e].to_vec());
                    start = e;
                }
                recs.push(row);
                outlen = 0;
                endlen = 0;
            }
            ReadRecordResult::End => return recs,
        }
    }
}

