/// Drive `read_record` over the given input chunks with output/end buffers
/// that start at `out_cap`/`ends_cap` slots and grow only when reported full.
fn parse_by_record(
    nfa: bool,
    chunks: &[Vec<u8>],
    out_cap: usize,
    ends_cap: usize,
) -> Csv {
    let mut rdr = reader(nfa);
    let mut out = vec![0u8; out_cap];
    let mut ends = vec![0usize; ends_cap];
    let (mut outpos, mut endpos) = (0usize, 0usize);
    let mut recs = Csv::new();

    let mut feed = |rdr: &mut Reader, mut data: &[u8],
                    out: &mut Vec<u8>, ends: &mut Vec<usize>,
                    outpos: &mut usize, endpos: &mut usize,
                    recs: &mut Csv|
     -> bool {
        loop {
            let (res, nin, nout, nend) = rdr.read_record(
                data,
                &mut out[*outpos..],
                &mut ends[*endpos..],
            );
            data = &data[nin..];
            *outpos += nout;
            *endpos += nend;
            match res {
                ReadRecordResult::InputEmpty => {
                    assert!(data.is_empty(), "unread input remains");
                    return false;
                }
                ReadRecordResult::OutputFull => {
                    out.resize(core::cmp::max(1, out.len() * 2), 0);
                }
                ReadRecordResult::OutputEndsFull => {
                    ends.resize(core::cmp::max(1, ends.len() * 2), 0);
                }
                ReadRecordResult::Record => {
                    let mut start = 0;
                    let mut row = Vec::new();
                    for &e in &ends[..*endpos] {
                        row.push(out[start..e].to_vec());
                        start = e;
                    }
                    recs.push(row);
                    *outpos = 0;
                    *endpos = 0;
                }
                ReadRecordResult::End => return true,
            }
        }
    };

    for chunk in chunks {
        if feed(
            &mut rdr,
            chunk,
            &mut out,
            &mut ends,
            &mut outpos,
            &mut endpos,
            &mut recs,
        ) {
            return recs;
        }
    }
    while !feed(
        &mut rdr,
        &[],
        &mut out,
        &mut ends,
        &mut outpos,
