//! High-level reader tests for UTF-8 BOM handling.

use std::io;

use csv::{ByteRecord, ErrorKind, ReaderBuilder, StringRecord};
use serde::Deserialize;

fn collect_string(data: &[u8], headers: bool, cap: usize) -> Vec<StringRecord> {
    let mut rdr = ReaderBuilder::new()
        .has_headers(headers)
        .buffer_capacity(cap)
        .from_reader(data);
    let mut out = Vec::new();
    for rec in rdr.records() {
        out.push(rec.unwrap());
    }
    out
}

fn collect_bytes(data: &[u8], headers: bool, cap: usize) -> Vec<ByteRecord> {
    let mut rdr = ReaderBuilder::new()
        .has_headers(headers)
        .buffer_capacity(cap)
        .from_reader(data);
    let mut out = Vec::new();
    for rec in rdr.byte_records() {
        out.push(rec.unwrap());
    }
    out
}

